local OverseaChatMainDialog = Class("OverseaChatMainDialog")

function OverseaChatMainDialog:__init()
    self.data = nil
    self.handler = nil
    self.privateChat = {}
    self.panelController = {}
    self._selectedIndex = 1
end

function OverseaChatMainDialog:__delete()
    self.data = nil
    self.controller = nil
    self.privateChat = nil
    self.panelController = nil
    self.handler = nil
end

function OverseaChatMainDialog:Awake()
    SetButtonAction(self.BlockDialogue, function()
        UIModule.BackDialog()
    end)
    self.panelController = {
        [ChatConstants.Channels.System]     = CfUtils.GetLuaScr(self.SystemPanel, SystemPanelPath),
        [ChatConstants.Channels.Private]    = CfUtils.GetLuaScr(self.FriendEntryPanel, FriendEntryPanel),
        [ChatConstants.Channels.Help]       = CfUtils.GetLuaScr(self.RecruitPanel, RecruitPanel),
        [ChatConstants.Channels.ClubHelp]   = CfUtils.GetLuaScr(self.RecruitPanel, ClubRecruitPanel),
        [ChatConstants.Channels.Fight]      = CfUtils.GetLuaScr(self.DialoguePanel, DialoguePanel),
        [ChatConstants.Channels.Single]     = CfUtils.GetLuaScr(self.DialoguePanel, DialoguePanel),
        [ChatConstants.Channels.Union]      = CfUtils.GetLuaScr(self.DialoguePanel, DialoguePanel),
        [ChatConstants.Channels.World]      = CfUtils.GetLuaScr(self.DialoguePanel, DialoguePanel),
        [ChatConstants.Channels.CrossWorld] = CfUtils.GetLuaScr(self.DialoguePanel, DialoguePanel),
    }
    KTool.SetActive(self.ClubRecruitPanel.gameObject,false)
    self:GetTabData()
    DreamSpaceStates.LockInput_ByFlag(DreamSpaceStates.InputLockState.Lock)
end

function OverseaChatMainDialog:GetTabData()
    local t = {}
    local social = AppService:GetInstance():GetSocialLine()
    ---@type ClubComponent
    local clubComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.ClubComponent)
    ---@type PlayerComponent
    local playerComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.PlayerComponent)
    local playerDojo = playerComponent:GetPlayerDojo()
    local chatChannelsStatus = checkTable(playerDojo.chatChannelsStatus)
    local function insert(data)
        -- 判断一下服务器开关
        if checkInt(chatChannelsStatus[tostring(social:ChannelToServerChannel(data.id))]) == 0 then
            table.insert(t, data)
        end
    end
    for id, v in pairs(ChatConstants.Channel_Labels) do
        if id == ChatConstants.Channels.Fight then
            if social.teamRoomId then
                insert({ id = id, name = v.name })
            end
        elseif id == ChatConstants.Channels.Help then
            if not social.teamRoomId and checkNumber(v.isOpen) == 1 then
                insert({ id = id, name = v.name })
            end
        elseif id == ChatConstants.Channels.Union then
            if social.clubRoomId and clubComponent:IsJoinClub() and checkNumber(v.isOpen) == 1 then
                insert({ id = id, name = v.name })
            end
        elseif id == ChatConstants.Channels.World then
            if GameUtils.IsChatWorldOpen() and checkNumber(v.isOpen) == 1 then
                insert({ id = id, name = v.name })
            end
        else
            if checkNumber(v.isOpen) == 1 then
                insert({ id = id, name = v.name })
            end
        end
    end
    self.data = t
end

function OverseaChatMainDialog:UpdateListView()
    if not self.TabListView.IsListViewInit then
        self.TabListView:InitGridView(#self.data + #self.privateChat, Bind(self, self.OnGetItemByIndex))
    else
        GameUtils.ReloadData(self.TabListView, #self.data + #self.privateChat)
    end
end

---刷新列表空节点
function OverseaChatMainDialog:RefreshEmptyNode()
    local channel = self:GetChannel()
    local isVisible = false
    local id = nil
    if channel == ChatConstants.Channels.Private then
        isVisible = #friendComp:GetFriendList() == 0
        id = ChatConstants.ChatTipsId.FRIEND
    elseif channel == ChatConstants.Channels.World then
        isVisible = #Social.worldData == 0
        id = ChatConstants.ChatTipsId.WORLD
    elseif channel == ChatConstants.Channels.System then
        isVisible = #Social.systemData == 0
        id = ChatConstants.ChatTipsId.SYSTEM
    elseif channel == ChatConstants.Channels.Union then
        isVisible = #Social.clubData == 0
        id = ChatConstants.ChatTipsId.CLUB
    elseif channel == ChatConstants.Channels.Help then
        isVisible = #Social.recruitData == 0
        id = ChatConstants.ChatTipsId.RECRUIT
    end

    CfUtils.SetActive(self.Empty, isVisible)
    if isVisible then
        ---@type EmptyNodeMB
        local emptyNodeEnv = CfUtils.GetLuaScr(self.Empty.transform:Find("EmptyNode"), "Game.Behaviours.EmptyNodeMB")
        if isNotNull(emptyNodeEnv) then
            ---@type ChatTipsVo
            local tipsVo = CfUtils.GetCfVo(AutoIds.IdSetting6093, "ChatTipsVo", id)
            emptyNodeEnv:SetText(tipsVo.txt)
        end
    end
end

function OverseaChatMainDialog:ChangePanel(index, isClick)
    local channel = self:GetChannel()
    KTool.SetActive(self.SystemPanel, channel == ChatConstants.Channels.System)
    KTool.SetActive(self.FriendEntryPanel, channel == ChatConstants.Channels.Private)
    KTool.SetActive(self.RecruitPanel, channel == ChatConstants.Channels.Help )
    KTool.SetActive(self.ClubRecruitPanel,channel == ChatConstants.Channels.ClubHelp)
    local DialogueShow = {
        [ChatConstants.Channels.Single] = true,
        [ChatConstants.Channels.Fight]  = true,
        [ChatConstants.Channels.Union]  = true,
        [ChatConstants.Channels.World]  = true,
        [ChatConstants.Channels.CrossWorld]  = true,
    }
    KTool.SetActive(self.DialoguePanel, DialogueShow[channel] == true)
    self:RefreshEmptyNode()
    if self.panelController[channel] then 
        self.panelController[channel]:Refresh(self, isClick)
    end
end

---RefreshPrivateData
---剧新聊聊天信息的
---@param data table
function OverseaChatMainDialog:RefreshPrivateData(data, isDelete)
    isDelete = checkBool(isDelete)
    local v, index = table.find(self.privateChat, function(v)
        return checkNumber(v.friendId) == checkNumber(data.friendId)
    end)
    if v and isDelete then
        ---查找到不插入,是删除操作
        table.remove(self.privateChat, index)
    elseif not v then
        table.insert(self.privateChat, data)
    end
    if #self.privateChat > 0 then
        if v and (not isDelete) then
            self._selectedIndex = #self.data + index
        else
            self._selectedIndex = #self.data + #self.privateChat
        end
    else
        self._selectedIndex = self:GetSelectedIndexByChannelId(ChatConstants.Channels.Private)
    end
    self:UpdateListView()
    self:ChangePanel(self._selectedIndex, true)
end

function OverseaChatMainDialog:OnGetItemByIndex(listView, index)
    if index < 0 then
        return nil
    end
    local cell = listView:NewListViewItem("Cell")
    ---@type OverseaChatTabCell
    local nodeEnv = CfUtils.GetLuaScr(cell.gameObject, TabCellPath)
    local position = index + 1
    local isSelected = position == self._selectedIndex
    if nodeEnv then
        nodeEnv:FreshSelectStatus(isSelected)
        if position <= #self.data then
            local data = self.data[position]
            nodeEnv:SetChannelInfo(position, data.name, checkNumber(data.id))
        else
            ---私聊天对话信息的列表
            local data = self.privateChat[position - #self.data]
            if data then
                nodeEnv:FreshPlayerData(position, data, isSelected)
            end
        end
        nodeEnv:SetClickCb(Bind(self, self.OnClickTabCell))
    end
    return cell
end

function OverseaChatMainDialog:OnClickTabCell(index)
    if self._selectedIndex == index then
        return
    end
    self._selectedIndex = index
    self:UpdateListView()
    self:ChangePanel(self._selectedIndex, true)
    self:UpdatePanelRedPointState()
end

function OverseaChatMainDialog:GetChannel()
    if self._selectedIndex > #self.data then
        return ChatConstants.Channels.Single
    else
        return self.data[self._selectedIndex].id
    end
end

function OverseaChatMainDialog:UpdatePanelRedPointState()
    local channel = self:GetChannel()
    local social = AppService:GetInstance():GetSocialLine()
    if channel == ChatConstants.Channels.Single then
        -- 点击时将消息状态变为已读
        local position = self._selectedIndex - #self.data
        local data = self.privateChat[position]
        local friendId = checkNumber(data.friendId)
        social:ReadUnreadMessage(friendId)
    elseif channel == ChatConstants.Channels.Fight then
        social:UnmarkNewMessage(ChatConstants.ChatServerChannel.Fight)
    elseif channel == ChatConstants.Channels.Union then
        social:UnmarkNewMessage(ChatConstants.ChatServerChannel.Union)
    elseif channel == ChatConstants.Channels.World then
        social:UnmarkNewMessage(ChatConstants.ChatServerChannel.World)
    end
end

function OverseaChatMainDialog:InitPrivateChat()
    local data = Social:GetRecentContacts()
    for i, v in ipairs(data) do
        local info = friendComp:GetFriendInfo(v)
        if info then
            table.insert(self.privateChat, info)
        end
    end
end

function OverseaChatMainDialog:GetSelectedIndexByChannelId(channelId)
    for i, v in ipairs(checkTable(self.data)) do
        if checkInt(v.id) == checkInt(channelId) then
            return i
        end
    end
    return 1
end

function OverseaChatMainDialog:HasChannel(channelId)
    for i, v in ipairs(checkTable(self.data)) do
        if checkInt(v.id) == checkInt(channelId) then
            return true
        end
    end
    return false
end

function OverseaChatMainDialog:OnShow()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        local isFinish = false
        --if not friendComp:HasFriendList() then
            friendComp:SyncFriendList(function()
                isFinish = true
            end)
        --else
        --    isFinish = true
        --end
        while not isFinish do
            coroutine.yield()
        end
        local parameters = self.controller.Argument.parameters
        if parameters and parameters.type and parameters.data then
            ----需要打开的页签
            self._selectedIndex = self:GetSelectedIndexByChannelId(parameters.type)
            local friendData = checkTable(parameters.data)
            self:RefreshPrivateData(friendData)
        else
            self:ChangePanel(self._selectedIndex, true)
            self:UpdatePanelRedPointState()
        end
    end))
    return coWait
end

function OverseaChatMainDialog:OnInitialize()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        local parameters = self.controller.Argument.parameters
        local friendData
        self:InitPrivateChat()
        if parameters and parameters.type then
            ----需要打开的页签
            self._selectedIndex = self:GetSelectedIndexByChannelId(parameters.type)
            if self.privateChat and parameters.data then
                ---私聊
                friendData = checkTable(parameters.data)
                local v, index = table.find(self.privateChat, function(v)
                    return checkNumber(v.friendId) == checkNumber(friendData.friendId)
                end)
                if not v then
                    table.insert(self.privateChat, friendData)
                end
            end
        end
        
        print('-->>', #self.data, #self.privateChat)
        self.handler = Events.AddListener(ChatConstants.EventNames.NEW_PRIVATE_RED_POINT_NOTIFY, function()
            self:UpdateListView()
            self:ChangePanel(self._selectedIndex)
        end)
        self.newSystemMsgHandler = Events.AddListener(ChatConstants.EventNames.NEW_SYSTEM_MESSAGE, function(data)
            CfUtils.SetActive(self.Empty, false)
        end)
        self.newRecruitMsgHandler = Events.AddListener(ChatConstants.EventNames.NEW_RECRUIT_MESSAGE, function(data)
            CfUtils.SetActive(self.Empty, false)
        end)
        self.newClubRecruitMsgHandler = Events.AddListener(ChatConstants.EventNames.NEW_CLUB_RECRUIT_MESSAGE, function(data)
            CfUtils.SetActive(self.Empty, false)
        end)
        self.newGroupMsgHandler = Events.AddListener(ChatConstants.EventNames.NEW_GROUP_CHAT_MESSAGE, function(data)
            CfUtils.SetActive(self.Empty, false)
        end)
        self.closeHandler = Events.AddListener(ChatConstants.EventNames.OVERSEA_CLOSE_CHAT_DIALOG, function(data)
            UIModule.CloseDialog(self.controller)
        end)
        self.switchHandler = Events.AddListener(ChatConstants.EventNames.CHAT_TAB_SWITCH, function(data)
            data = checkTable(data)
            self._selectedIndex = self:GetSelectedIndexByChannelId(data.type)
            if data.friendData then
                self:RefreshPrivateData(data.friendData)
            else
                self:ChangePanel(self._selectedIndex, true)
                self:UpdatePanelRedPointState()
            end
        end)
        
        if friendData and self._selectedIndex == self:GetSelectedIndexByChannelId(ChatConstants.Channels.Private) then
            ---直接跳转到私聊
        else
            KTool.SetActive(self.SystemPanel, self._selectedIndex == self:GetSelectedIndexByChannelId(ChatConstants.Channels.System))
            KTool.SetActive(self.FriendEntryPanel, self._selectedIndex == self:GetSelectedIndexByChannelId(ChatConstants.Channels.Private))
            KTool.SetActive(self.DialoguePanel, self._selectedIndex > self:GetSelectedIndexByChannelId(ChatConstants.Channels.Help))
            if self:HasChannel(ChatConstants.Channels.Help) then
                KTool.SetActive(self.RecruitPanel, self._selectedIndex == self:GetSelectedIndexByChannelId(ChatConstants.Channels.Help))
            end
            self:UpdateListView()
        end
    end))
    return coWait
end

function OverseaChatMainDialog:OnFinalize()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        Events.RemoveListener(ChatConstants.EventNames.NEW_PRIVATE_RED_POINT_NOTIFY, self.handler)
        Events.RemoveListener(ChatConstants.EventNames.NEW_SYSTEM_MESSAGE, self.newSystemMsgHandler)
        Events.RemoveListener(ChatConstants.EventNames.NEW_RECRUIT_MESSAGE, self.newRecruitMsgHandler)
        Events.RemoveListener(ChatConstants.EventNames.NEW_CLUB_RECRUIT_MESSAGE, self.newClubRecruitMsgHandler)
        Events.RemoveListener(ChatConstants.EventNames.NEW_GROUP_CHAT_MESSAGE, self.newGroupMsgHandler)
        Events.RemoveListener(ChatConstants.EventNames.OVERSEA_CLOSE_CHAT_DIALOG, self.closeHandler)
        Events.RemoveListener(ChatConstants.EventNames.CHAT_TAB_SWITCH, self.switchHandler)
        DreamSpaceStates.LockInput_ByFlag(DreamSpaceStates.InputLockState.Unlock)
        self.handler = nil
        self.controller = nil --C#托管堆GC
        self:Delete()
        self = nil
    end))
    return coWait
end

return OverseaChatMainDialog